from math import lcm
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any denomination.

    Coins of different denominations cannot be combined. ``coins`` contains
    1-15 distinct positive integers, each at most 25, and ``k`` is 1-based
    with 1 <= k <= 2 * 10**9. The input list is not modified.

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # A denomination divisible by a smaller one adds no new amounts.
    denominations = []
    for coin in sorted(coins):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    if len(denominations) == 1:
        return denominations[0] * k

    # The smallest denomination alone supplies k amounts up to this bound.
    upper = denominations[0] * k

    # Inclusion-exclusion counts the union of multiples without duplicates.
    # Aggregate subsets with the same LCM, cancelling zero coefficients.
    # LCMs above the search bound cannot contribute to any count.
    coefficients = {}
    for coin in denominations:
        changes = {coin: 1}
        for multiple, coefficient in coefficients.items():
            common = lcm(multiple, coin)
            if common <= upper:
                changes[common] = changes.get(common, 0) - coefficient
        for multiple, change in changes.items():
            coefficient = coefficients.get(multiple, 0) + change
            if coefficient:
                coefficients[multiple] = coefficient
            else:
                coefficients.pop(multiple, None)

    terms = tuple(coefficients.items())
    lower = denominations[0]
    while lower < upper:
        middle = (lower + upper) // 2
        count = sum(coefficient * (middle // multiple)
                    for multiple, coefficient in terms)
        if count >= k:
            upper = middle
        else:
            lower = middle + 1
    return lower
